-- The company master: one row per real-world company.
create table careercloud.companies (
  id                     text primary key check (id ~ '^co_[0-9a-f]{32}$'),
  workspace_id           uuid not null references careercloud.workspaces (id) on delete cascade,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  created_by             uuid,
  version                integer not null default 1,
  name                   text not null check (char_length(name) <= 300),
  normalized_name        text check (char_length(normalized_name) <= 300),
  legal_name             text check (char_length(legal_name) <= 300),
  aliases                text[] not null default '{}'::text[],
  domain                 text check (char_length(domain) <= 253),
  website                text check (char_length(website) <= 2048),
  careers_url            text check (char_length(careers_url) <= 2048),
  linkedin_url           text check (char_length(linkedin_url) <= 500),
  industry               text check (char_length(industry) <= 200),
  sub_industry           text check (char_length(sub_industry) <= 200),
  sic_codes              text[] not null default '{}'::text[],
  naics_codes            text[] not null default '{}'::text[],
  country                text check (char_length(country) <= 100),
  state                  text check (char_length(state) <= 100),
  city                   text check (char_length(city) <= 120),
  employee_range         text check (char_length(employee_range) <= 60),
  employee_count         integer check (employee_count >= 0),
  revenue_range          text check (char_length(revenue_range) <= 60),
  revenue_usd            double precision check (revenue_usd >= 0),
  technologies           text[] not null default '{}'::text[],
  ats                    text check (char_length(ats) <= 100),
  lifecycle              text not null default 'prospect' check (lifecycle in ('prospect', 'account', 'customer', 'partner', 'disqualified')),
  status                 text not null default 'active' check (status in ('active', 'merged', 'inactive', 'archived')),
  merged_into_id         text check (char_length(merged_into_id) <= 40),
  parent_company_id      text check (char_length(parent_company_id) <= 40),
  hiring_count           integer not null default 0 check (hiring_count >= 0),
  hiring_velocity        double precision,
  hiring_signals         text[] not null default '{}'::text[],
  account_score          double precision check (account_score >= 0 and account_score <= 100),
  hiring_score           double precision check (hiring_score >= 0 and hiring_score <= 100),
  opportunity_score      double precision check (opportunity_score >= 0 and opportunity_score <= 100),
  score_breakdown        jsonb not null default '{}'::jsonb,
  confidence             double precision check (confidence >= 0 and confidence <= 1),
  owner_id               uuid,
  tags                   text[] not null default '{}'::text[],
  custom_fields          jsonb not null default '{}'::jsonb,
  first_seen_at          timestamptz,
  last_seen_at           timestamptz,
  last_crawled_at        timestamptz,
  source_count           integer not null default 0 check (source_count >= 0),
  description            text check (char_length(description) <= 4000)
);

