  idempotency_key        text check (char_length(idempotency_key) <= 200),
  entity_type            text check (char_length(entity_type) <= 40),
  entity_id              text check (char_length(entity_id) <= 40)
);

create index platform_tasks_by_ws_created on careercloud.platform_tasks (workspace_id, created_at desc, id desc);
create index platform_tasks_by_ws_kind on careercloud.platform_tasks (workspace_id, kind);
create index platform_tasks_by_ws_status on careercloud.platform_tasks (workspace_id, status);
create unique index platform_tasks_uq_idempotency_key on careercloud.platform_tasks (workspace_id, idempotency_key) where idempotency_key is not null;
create trigger platform_tasks_guard before update on careercloud.platform_tasks
  for each row execute function careercloud.guard_platform_row();
alter table careercloud.platform_tasks enable row level security;
create policy platform_tasks_select on careercloud.platform_tasks for select to authenticated
  using (careercloud.is_member(workspace_id));
grant select on careercloud.platform_tasks to authenticated;

-- ---------------------------------------------------------------------------
-- exports
create table careercloud.exports (
  id                     text primary key check (id ~ '^ex_[0-9a-f]{32}$'),
  workspace_id           uuid not null references careercloud.workspaces (id) on delete cascade,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  created_by             uuid,
  version                integer not null default 1,
  entity_type            text not null check (char_length(entity_type) <= 40),
  format                 text not null default 'csv' check (format in ('csv', 'xlsx', 'json')),
  filters                jsonb not null default '{}'::jsonb,
  status                 text not null default 'queued' check (status in ('queued', 'completed', 'failed')),
  row_count              integer not null default 0 check (row_count >= 0),
  storage_key            text check (char_length(storage_key) <= 512),
  filename               text check (char_length(filename) <= 200),
  sha256                 text check (char_length(sha256) <= 64),
  size_bytes             bigint check (size_bytes >= 0),
  error                  text check (char_length(error) <= 2000)
);

create index exports_by_ws_created on careercloud.exports (workspace_id, created_at desc, id desc);
create index exports_by_ws_format on careercloud.exports (workspace_id, format);
create index exports_by_ws_status on careercloud.exports (workspace_id, status);
create trigger exports_guard before update on careercloud.exports
  for each row execute function careercloud.guard_platform_row();
alter table careercloud.exports enable row level security;
create policy exports_select on careercloud.exports for select to authenticated
  using (careercloud.is_member(workspace_id));
create policy exports_insert on careercloud.exports for insert to authenticated
  with check (careercloud.can_write(workspace_id) and created_by = auth.uid());
create policy exports_update on careercloud.exports for update to authenticated
  using (careercloud.can_write(workspace_id)) with check (careercloud.can_write(workspace_id));
create policy exports_delete on careercloud.exports for delete to authenticated
  using (careercloud.can_write(workspace_id));
grant select, insert, update, delete on careercloud.exports to authenticated;

-- ---------------------------------------------------------------------------
-- audit_log
create table careercloud.audit_log (
  id                     text primary key check (id ~ '^au_[0-9a-f]{32}$'),
  workspace_id           uuid not null references careercloud.workspaces (id) on delete cascade,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  created_by             uuid,
  version                integer not null default 1,
  actor_id               uuid,
  actor_kind             text not null default 'user' check (actor_kind in ('user', 'system', 'agent', 'workflow')),
  action                 text not null check (char_length(action) <= 100),
  entity_type            text check (char_length(entity_type) <= 40),
  entity_id              text check (char_length(entity_id) <= 40),
  summary                text check (char_length(summary) <= 1000),
  changes                jsonb not null default '{}'::jsonb,
  request_id             text check (char_length(request_id) <= 100)
);

create index audit_log_by_ws_created on careercloud.audit_log (workspace_id, created_at desc, id desc);
create index audit_log_by_ws_actor_kind on careercloud.audit_log (workspace_id, actor_kind);
create index audit_log_by_ws_action on careercloud.audit_log (workspace_id, action);
create index audit_log_by_ws_entity_type on careercloud.audit_log (workspace_id, entity_type);
create index audit_log_by_ws_entity_id on careercloud.audit_log (workspace_id, entity_id);
create trigger audit_log_guard before update on careercloud.audit_log
  for each row execute function careercloud.guard_platform_row();
alter table careercloud.audit_log enable row level security;
create policy audit_log_select on careercloud.audit_log for select to authenticated
  using (careercloud.is_member(workspace_id));
create policy audit_log_insert on careercloud.audit_log for insert to authenticated
  with check (careercloud.can_write(workspace_id) and created_by = auth.uid());
grant select, insert on careercloud.audit_log to authenticated;

-- ---------------------------------------------------------------------------
-- idempotency_keys
create table careercloud.idempotency_keys (
  id                     text primary key check (id ~ '^ik_[0-9a-f]{32}$'),
  workspace_id           uuid not null references careercloud.workspaces (id) on delete cascade,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
