  version                integer not null default 1,
  key                    text not null check (char_length(key) <= 200),
  method                 text not null check (char_length(method) <= 10),
  path                   text not null check (char_length(path) <= 500),
  request_hash           text not null check (char_length(request_hash) <= 64),
  status_code            integer not null,
  response               jsonb not null default '{}'::jsonb
);

create index idempotency_keys_by_ws_created on careercloud.idempotency_keys (workspace_id, created_at desc, id desc);
create unique index idempotency_keys_uq_key on careercloud.idempotency_keys (workspace_id, key);
create trigger idempotency_keys_guard before update on careercloud.idempotency_keys
  for each row execute function careercloud.guard_platform_row();
alter table careercloud.idempotency_keys enable row level security;
create policy idempotency_keys_select on careercloud.idempotency_keys for select to authenticated
  using (careercloud.is_member(workspace_id));
create policy idempotency_keys_insert on careercloud.idempotency_keys for insert to authenticated
  with check (careercloud.can_write(workspace_id) and created_by = auth.uid());
grant select, insert on careercloud.idempotency_keys to authenticated;

-- ---------------------------------------------------------------------------
-- Supabase's anonymous role gets nothing in this schema.
-- ---------------------------------------------------------------------------

do $anon$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on all tables in schema careercloud from anon;
    revoke all on all functions in schema careercloud from anon;
  end if;
end
$anon$;
